import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    include: ['test/**/*.test.ts'],
    // Each command test drives real `git` against a temp repository, so the
    // suite is I/O bound rather than CPU bound.
    testTimeout: 120_000,
    hookTimeout: 60_000,
    // Fixtures share ~/.workforge state (backups, audit logs), so files must
    // not run concurrently.
    fileParallelism: false
  }
});

import { describe, it, expect, afterAll, vi } from 'vitest';
import { writeFileSync, readFileSync } from 'fs';
import * as path from 'path';
import { EnvFileParser } from '../src/core/EnvFileParser.js';
import { EnvSyncer } from '../src/core/EnvSyncer.js';
import { EnvDiffer } from '../src/core/EnvDiffer.js';
import { SyncDecision } from '../src/types/index.js';
import { makeTempDir, cleanupFixtures } from './helpers/fixtures.js';

const dir = makeTempDir('wf-env-');
const parser = new EnvFileParser();

afterAll(cleanupFixtures);

let counter = 0;
function envFile(content: string): string {
  const file = path.join(dir, `env-${counter++}.env`);
  writeFileSync(file, content, 'utf8');
  return file;
}

/** Parse and re-render through the same path EnvSyncer.sync uses. */
function roundTrip(content: string): string {
  const parsed = parser.parseFile(envFile(content));
  return parser.stringify(parsed.variables, parsed.trailingTrivia);
}

function decision(over: Partial<SyncDecision> = {}): SyncDecision {
  return {
    addedKeys: new Set(),
    modifiedKeys: new Set(),
    removedKeys: new Set(),
    syncAll: false,
    ...over
  };
}

describe('inline comments', () => {
  it('keeps a "#" that is part of an unquoted value', () => {
    const vars = parser.parse(envFile('API_KEY=sk_live_51H8x#special\n'));
    expect(vars.get('API_KEY')?.value).toBe('sk_live_51H8x#special');
    expect(vars.get('API_KEY')?.comment).toBeUndefined();
  });

  it('still treats a whitespace-separated "#" as a comment', () => {
    const vars = parser.parse(envFile('FOO=bar # a real comment\n'));
    expect(vars.get('FOO')?.value).toBe('bar');
    expect(vars.get('FOO')?.comment).toBe('# a real comment');
  });

  it('keeps "//" inside a URL', () => {
    const vars = parser.parse(envFile('URL=http://example.com/path\n'));
    expect(vars.get('URL')?.value).toBe('http://example.com/path');
  });

  it('round-trips a hash-bearing value byte-identically', () => {
    const src = 'API_KEY=sk_live_51H8x#special\n';
    expect(roundTrip(src)).toBe(src);
  });
});

describe('escape sequences', () => {
  it('decodes a Windows path without inventing a newline', () => {
    const vars = parser.parse(envFile('WINPATH="C:\\\\Users\\\\name"\n'));
    expect(vars.get('WINPATH')?.value).toBe('C:\\Users\\name');
  });

  it('keeps a Windows path on one line after a rewrite', () => {
    const src = 'WINPATH="C:\\\\Users\\\\name"\n';
    const out = roundTrip(src);
    expect(out).toBe(src);
    expect(out.trim().split('\n')).toHaveLength(1);
  });

  it('still decodes \\n to a newline', () => {
    const vars = parser.parse(envFile('MULTI="a\\nb"\n'));
    expect(vars.get('MULTI')?.value).toBe('a\nb');
  });

  it('round-trips an escaped newline', () => {
    const src = 'MULTI="a\\nb"\n';
    expect(roundTrip(src)).toBe(src);
  });
});

describe('formatting fidelity', () => {
  it('preserves standalone comments, blank lines and trailing trivia', () => {
    const src =
      '# Database configuration\n' +
      'DATABASE_URL=postgres://localhost/db\n' +
      '\n' +
      '# API settings\n' +
      'API_KEY=abc\n' +
      'FOO=bar\n' +
      '\n' +
      '# trailing note\n';
    expect(roundTrip(src)).toBe(src);
  });

  it('normalises CRLF without leaking a carriage return into values', () => {
    const vars = parser.parse(envFile('KEY="line1\r\nline2"\r\nFOO=bar\r\n'));
    expect(vars.get('KEY')?.value).toBe('line1\nline2');
    expect(vars.get('KEY')?.value).not.toContain('\r');
  });
});

describe('duplicate keys', () => {
  it('keeps the last value and warns', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => undefined);
    const vars = parser.parse(envFile('FOO=first\nBAR=x\nFOO=second\n'));
    const messages = warn.mock.calls.map(call => String(call[0]));
    warn.mockRestore();

    expect(vars.get('FOO')?.value).toBe('second');
    expect(messages.some(m => /duplicate/i.test(m) && m.includes('FOO'))).toBe(true);
  });
});

describe('EnvSyncer', () => {
  it('appends added variables instead of inserting them mid-file', async () => {
    const target = envFile('AAA=1\nBBB=2\nCCC=3\n');
    const source = envFile('ZZZ=new\nAAA=1\nBBB=2\nCCC=3\n');

    const diff = new EnvDiffer().compare(source, target);
    await new EnvSyncer().sync(source, target, diff, decision({ addedKeys: new Set(['ZZZ']) }));

    expect(readFileSync(target, 'utf8')).toBe('AAA=1\nBBB=2\nCCC=3\nZZZ=new\n');
  });

  it('leaves every unselected variable byte-identical', async () => {
    const original =
      '# Database configuration\n' +
      'DATABASE_URL=postgres://localhost/db\n' +
      '\n' +
      '# API settings\n' +
      'API_KEY=sk_live_51H8x#special\n' +
      'WINPATH="C:\\\\Users\\\\name"\n' +
      'FOO=bar\n';
    const target = envFile(original);
    const source = envFile('BAZ=qux\n');

    const diff = new EnvDiffer().compare(source, target);
    const result = await new EnvSyncer().sync(
      source,
      target,
      diff,
      decision({ addedKeys: new Set(['BAZ']) })
    );

    expect(result.success).toBe(true);
    expect(readFileSync(target, 'utf8')).toBe(original + 'BAZ=qux\n');
  });

  it('applies a modification while preserving surrounding formatting', async () => {
    const target = envFile('# keep me\nFOO=old\nBAR=untouched\n');
    const source = envFile('FOO=new\nBAR=untouched\n');

    const diff = new EnvDiffer().compare(source, target);
    const result = await new EnvSyncer().sync(
      source,
      target,
      diff,
      decision({ modifiedKeys: new Set(['FOO']) })
    );

    expect(result.success).toBe(true);
    const out = readFileSync(target, 'utf8');
    expect(out).toContain('# keep me');
    expect(out).toContain('FOO=new');
    expect(out).toContain('BAR=untouched');
  });

  it('refuses to write when an unselected variable would change', async () => {
    const target = envFile('SAFE=keep\nOTHER=x\n');
    const source = envFile('SAFE=keep\nOTHER=x\nNEW=1\n');
    const before = readFileSync(target, 'utf8');

    const diff = new EnvDiffer().compare(source, target);

    // Corrupt the merge by claiming an untouched key is unchanged while the
    // rendered output drops it — the guard must catch the drift.
    const syncer = new EnvSyncer();
    const merge = Reflect.get(syncer, 'mergeVariables') as unknown;
    Reflect.set(syncer, 'mergeVariables', function corruptedMerge(this: unknown) {
      const vars = (merge as (...a: unknown[]) => Map<string, unknown>).apply(this, arguments as never);
      vars.delete('OTHER');
      return vars;
    });

    const result = await syncer.sync(source, target, diff, decision({ addedKeys: new Set(['NEW']) }));

    expect(result.success).toBe(false);
    expect(result.error).toMatch(/Refusing to write/);
    expect(readFileSync(target, 'utf8')).toBe(before);
  });
});

import { describe, it, expect, afterAll } from 'vitest';
import { existsSync, readFileSync, writeFileSync, rmSync, mkdirSync, readdirSync } from 'fs';
import * as path from 'path';
import { WorktreeResolver } from '../src/core/WorktreeResolver.js';
import { WorktreeRemover } from '../src/core/WorktreeRemover.js';
import { AuditLogger } from '../src/core/AuditLogger.js';
import { ProjectIdentifier } from '../src/core/ProjectIdentifier.js';
import { ListDisplay } from '../src/ui/ListDisplay.js';
import { toSingleLine } from '../src/utils/strings.js';
import { WorktreeInfo, AuditOperation } from '../src/types/index.js';
import { makeRepo, cleanupFixtures, runCli, gitIn } from './helpers/fixtures.js';

afterAll(cleanupFixtures);

describe('WorktreeResolver: main repository detection', () => {
  it('marks the main worktree of an ordinary (non-bare) repository', async () => {
    const repo = makeRepo({ primary: 'release' });
    runCli(repo.local, ['create', '-t', 'feat', '-n', 'one', '-y']);

    const worktrees = await new WorktreeResolver().getWorktrees(repo.local);

    expect(worktrees.filter(w => w.isMainRepo)).toHaveLength(1);
    expect(worktrees.find(w => w.isMainRepo)?.path).toBe(repo.local);
    expect(worktrees.find(w => w.path.endsWith('feat/one'))?.isMainRepo).toBe(false);
  });

  it('records a real commit timestamp for age sorting', async () => {
    const repo = makeRepo({ primary: 'release' });

    const worktrees = await new WorktreeResolver().getWorktrees(repo.local);

    expect(worktrees[0].commitTimestamp).toBeTypeOf('number');
    expect(worktrees[0].commitTimestamp).toBeGreaterThan(0);
  });
});

describe('ListDisplay: --sort age', () => {
  it('orders by commit time, not by commit hash', () => {
    const base = {
      isMainRepo: false,
      isLocked: false,
      isPrunable: false
    };

    // Hashes are deliberately ordered opposite to the timestamps: a
    // hash-based sort would put "aaa" (oldest) first.
    const worktrees: WorktreeInfo[] = [
      { ...base, path: '/w/old', branchName: 'old', commitHash: 'fff111', commitTimestamp: 1000 },
      { ...base, path: '/w/new', branchName: 'new', commitHash: 'aaa999', commitTimestamp: 9000 },
      { ...base, path: '/w/mid', branchName: 'mid', commitHash: 'ccc555', commitTimestamp: 5000 }
    ];

    const display = new ListDisplay();
    const sort = Reflect.get(display, 'sortWorktrees') as (
      w: WorktreeInfo[],
      by: string
    ) => WorktreeInfo[];
    const sorted = sort.call(display, worktrees, 'age');

    expect(sorted.map(w => w.branchName)).toEqual(['new', 'mid', 'old']);
  });
});

describe('WorktreeRemover', () => {
  it('removes a locked worktree when --force is given', async () => {
    const repo = makeRepo({ primary: 'release' });
    runCli(repo.local, ['create', '-t', 'feat', '-n', 'locked', '-y']);

    const worktreePath = path.join(repo.root, 'feat/locked');
    gitIn(repo.local, ['worktree', 'lock', worktreePath, '--reason', 'testing']);

    const worktrees = await new WorktreeResolver().getWorktrees(repo.local);
    const target = worktrees.find(w => w.path === worktreePath);
    expect(target?.isLocked).toBe(true);

    const result = await new WorktreeRemover().remove(target as WorktreeInfo, true, repo.local);

    expect(result.success).toBe(true);
    expect(existsSync(worktreePath)).toBe(false);
  });

  it('prunes only the requested worktree, leaving other prunable ones alone', async () => {
    const repo = makeRepo({ primary: 'release' });
    runCli(repo.local, ['create', '-t', 'feat', '-n', 'gone', '-y']);
    runCli(repo.local, ['create', '-t', 'feat', '-n', 'alsogone', '-y']);

    // Both directories vanish, so git reports both as prunable.
    rmSync(path.join(repo.root, 'feat/gone'), { recursive: true, force: true });
    rmSync(path.join(repo.root, 'feat/alsogone'), { recursive: true, force: true });

    const before = await new WorktreeResolver().getWorktrees(repo.local);
    expect(before.filter(w => w.isPrunable)).toHaveLength(2);

    const target = before.find(w => w.path.endsWith('feat/gone'));
    const result = await new WorktreeRemover().remove(target as WorktreeInfo, false, repo.local);

    expect(result.success).toBe(true);

    const after = await new WorktreeResolver().getWorktrees(repo.local);
    expect(after.some(w => w.path.endsWith('feat/gone'))).toBe(false);
    // The one the user did not ask about must still be registered.
    expect(after.some(w => w.path.endsWith('feat/alsogone'))).toBe(true);
  });

  it('explains an uncommitted-changes refusal in its own words', async () => {
    const repo = makeRepo({ primary: 'release' });
    runCli(repo.local, ['create', '-t', 'feat', '-n', 'dirty', '-y']);

    const worktreePath = path.join(repo.root, 'feat/dirty');
    writeFileSync(path.join(worktreePath, 'tracked.txt'), 'x\n', 'utf8');
    gitIn(worktreePath, ['add', '-A']);
    gitIn(worktreePath, ['-c', 'user.email=t@t.t', '-c', 'user.name=T', 'commit', '-qm', 'add']);
    writeFileSync(path.join(worktreePath, 'tracked.txt'), 'modified\n', 'utf8');

    const worktrees = await new WorktreeResolver().getWorktrees(repo.local);
    const target = worktrees.find(w => w.path === worktreePath);

    const result = await new WorktreeRemover().remove(target as WorktreeInfo, false, repo.local);

    expect(result.success).toBe(false);
    expect(result.message).toBe('Worktree has uncommitted changes. Commit, stash, or use --force.');
  });
});

describe('AuditLogger', () => {
  const operation = (source: string): AuditOperation =>
    ({
      timestamp: new Date().toISOString(),
      operation: 'sync',
      source,
      target: 'Main (test)',
      changesApplied: { added: 1, modified: 0, removed: 0 },
      variableDetails: { added: ['A'], modified: [], removed: [] },
      success: true,
      backupCreated: false
    }) as AuditOperation;

  it('preserves a corrupt history file instead of overwriting it', () => {
    const repo = makeRepo({ primary: 'release' });
    const projectDir = ProjectIdentifier.getProjectDir(repo.local);
    mkdirSync(projectDir, { recursive: true });

    const historyPath = path.join(projectDir, 'sync-history.json');
    writeFileSync(historyPath, '[{"broken": true,,,]', 'utf8');

    new AuditLogger().log(operation('Worktree (a)'), repo.local);

    const salvaged = readFileSync(historyPath, 'utf8');
    expect(JSON.parse(salvaged)).toHaveLength(1);

    // The unreadable original must still exist somewhere.
    const preserved = readdirSync(projectDir).filter(f => f.includes('.corrupt-'));
    expect(preserved.length).toBeGreaterThan(0);
    expect(readFileSync(path.join(projectDir, preserved[0]), 'utf8')).toBe('[{"broken": true,,,]');
  });

  it('keeps every entry when several loggers write at once', () => {
    const repo = makeRepo({ primary: 'release' });
    const projectDir = ProjectIdentifier.getProjectDir(repo.local);
    rmSync(path.join(projectDir, 'sync-history.json'), { force: true });

    for (let i = 0; i < 8; i++) {
      new AuditLogger().log(operation(`Worktree (${i})`), repo.local);
    }

    const history = JSON.parse(readFileSync(path.join(projectDir, 'sync-history.json'), 'utf8'));
    expect(history).toHaveLength(8);
  });
});

describe('toSingleLine', () => {
  it('escapes newlines, tabs and carriage returns visibly', () => {
    expect(toSingleLine('line1\nline2')).toBe('line1\\nline2');
    expect(toSingleLine('a\tb')).toBe('a\\tb');
    expect(toSingleLine('a\r\nb')).toBe('a\\r\\nb');
  });

  it('leaves ordinary values untouched apart from backslashes', () => {
    expect(toSingleLine('postgres://localhost/db')).toBe('postgres://localhost/db');
    expect(toSingleLine('C:\\Users')).toBe('C:\\\\Users');
  });

  it('never emits a real line break', () => {
    expect(toSingleLine('a\nb\nc')).not.toContain('\n');
  });
});

describe('sync-env: --between', () => {
  it('refuses to guess a direction when combined with --yes', () => {
    const repo = makeRepo({ primary: 'release' });
    runCli(repo.local, ['create', '-t', 'feat', '-n', 'bidi', '-y']);

    writeFileSync(path.join(repo.local, '.env'), 'SHARED=main\n', 'utf8');
    writeFileSync(path.join(repo.root, 'feat/bidi/.env'), 'SHARED=worktree\nEXTRA=1\n', 'utf8');
    const before = readFileSync(path.join(repo.local, '.env'), 'utf8');

    const run = runCli(repo.local, [
      'sync-env',
      '--between',
      path.join(repo.root, 'feat/bidi'),
      '--yes'
    ]);

    expect(run.status).not.toBe(0);
    expect(run.output).toContain('cannot be used with --yes');
    expect(readFileSync(path.join(repo.local, '.env'), 'utf8')).toBe(before);
  });
});

import { describe, it, expect, afterAll } from 'vitest';
import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'fs';
import * as path from 'path';
import {
  makeRepo,
  makeTempDir,
  cleanupFixtures,
  runCli,
  gitIn,
  branchExists
} from './helpers/fixtures.js';

afterAll(cleanupFixtures);

describe('create: base branch resolution', () => {
  it('forks from the remote tip, not the stale local branch', () => {
    const repo = makeRepo({ primary: 'release', advanceRemote: true });

    // The clone's local `release` is behind; only origin/release has the new commit.
    expect(gitIn(repo.local, ['rev-parse', '--short', 'release'])).not.toBe(
      repo.remoteTip('release')
    );

    const run = runCli(repo.local, ['create', '-t', 'feat', '-n', 'a', '-y']);

    expect(run.output).toContain('Detected primary branch: release');
    expect(run.output).toContain('Branching from origin/release');
    expect(repo.tipOf('feat/a')).toBe(repo.remoteTip('release'));
    expect(readFileSync(path.join(repo.root, 'feat/a/file.txt'), 'utf8').trim()).toBe('v2');
  });

  it('does not set the base branch as the new branch upstream', () => {
    const repo = makeRepo({ primary: 'release' });
    runCli(repo.local, ['create', '-t', 'feat', '-n', 'a', '-y']);

    const upstream = gitIn(path.join(repo.root, 'feat/a'), [
      'rev-parse',
      '--abbrev-ref',
      '--symbolic-full-name',
      '@{u}'
    ]);
    expect(upstream).toBe('');
  });

  it('accepts a base that exists only on the remote', () => {
    const repo = makeRepo({ primary: 'main', branches: ['develop'] });
    expect(branchExists(repo.local, 'develop')).toBe(false);

    const run = runCli(repo.local, ['create', '-t', 'fix', '-n', 'b', '-b', 'develop', '-y']);

    expect(run.output).toContain('Workspace created successfully');
    expect(run.output).toContain('Branching from origin/develop');
    expect(repo.tipOf('fix/b')).toBe(repo.remoteTip('develop'));
  });

  it('never overrides an explicit --base with auto-detection', () => {
    const repo = makeRepo({ primary: 'release', branches: ['main'] });

    const run = runCli(repo.local, ['create', '-t', 'feat', '-n', 'c', '-b', 'main', '-y']);

    expect(run.output).toContain('Using base branch from --base: main');
    expect(run.output).not.toContain('Detected primary branch');
    expect(repo.tipOf('feat/c')).toBe(repo.remoteTip('main'));
  });

  it('accepts a base already qualified as origin/<branch>', () => {
    const repo = makeRepo({ primary: 'release', advanceRemote: true });

    const run = runCli(repo.local, ['create', '-t', 'feat', '-n', 'i', '-b', 'origin/release', '-y']);

    expect(run.output).toContain('Branching from origin/release');
    expect(repo.tipOf('feat/i')).toBe(repo.remoteTip('release'));
  });

  it('accepts a tag as the base', () => {
    const repo = makeRepo({ primary: 'release' });
    gitIn(repo.local, ['tag', 'v0.1']);

    const run = runCli(repo.local, ['create', '-t', 'chore', '-n', 'j', '-b', 'v0.1', '-y']);

    expect(run.output).toContain('commit-ish');
    expect(repo.tipOf('chore/j')).toBe(gitIn(repo.local, ['rev-parse', '--short', 'v0.1']));
  });
});

describe('create: primary branch inference', () => {
  it('queries the remote when origin/HEAD is not cached locally', () => {
    const repo = makeRepo({ primary: 'release', advanceRemote: true });
    gitIn(repo.local, ['symbolic-ref', '-d', 'refs/remotes/origin/HEAD']);

    const run = runCli(repo.local, ['create', '-t', 'feat', '-n', 'g', '-y']);

    expect(run.output).toContain('Detected primary branch: release');
    expect(repo.tipOf('feat/g')).toBe(repo.remoteTip('release'));
    expect(gitIn(repo.local, ['symbolic-ref', '--short', 'refs/remotes/origin/HEAD'])).toBe(
      'origin/release'
    );
  });

  it('picks up a default branch the remote has since renamed', () => {
    const repo = makeRepo({ primary: 'master' });

    // The remote renames master -> main after the clone was taken.
    gitIn(repo.seed, ['checkout', '--quiet', '-b', 'main']);
    gitIn(repo.seed, ['push', '--quiet', 'origin', 'main']);
    gitIn(repo.remote, ['symbolic-ref', 'HEAD', 'refs/heads/main']);
    gitIn(repo.seed, ['push', '--quiet', 'origin', '--delete', 'master']);

    expect(gitIn(repo.local, ['symbolic-ref', '--short', 'refs/remotes/origin/HEAD'])).toBe(
      'origin/master'
    );

    const run = runCli(repo.local, ['create', '-t', 'feat', '-n', 'a1', '-y']);

    expect(run.output).toContain('Detected primary branch: main');
    expect(gitIn(repo.local, ['symbolic-ref', '--short', 'refs/remotes/origin/HEAD'])).toBe(
      'origin/main'
    );
  });

  it('uses a remote that is not named origin', () => {
    const repo = makeRepo({ primary: 'release', advanceRemote: true });
    gitIn(repo.local, ['remote', 'rename', 'origin', 'upstream']);

    const run = runCli(repo.local, ['create', '-t', 'feat', '-n', 'f', '-y']);

    expect(run.output).toContain('upstream');
    expect(repo.tipOf('feat/f')).toBe(repo.remoteTip('release'));
  });
});

describe('create: degraded environments', () => {
  it('warns but still creates a worktree when no remote is configured', () => {
    const root = makeTempDir('wf-noremote-');
    const local = path.join(root, 'local');
    mkdirSync(local, { recursive: true });
    gitIn(local, ['init', '--quiet']);
    gitIn(local, ['config', 'user.email', 'test@example.com']);
    gitIn(local, ['config', 'user.name', 'Test']);
    gitIn(local, ['checkout', '--quiet', '-b', 'release']);
    writeFileSync(path.join(local, 'f.txt'), 'x\n', 'utf8');
    gitIn(local, ['add', '-A']);
    gitIn(local, ['commit', '--quiet', '-m', 'c1']);

    const run = runCli(local, ['create', '-t', 'feat', '-n', 'd', '-y']);

    expect(run.output).toContain('No Git remote configured');
    expect(run.output).toContain('Workspace created successfully');
    expect(run.output).toContain('warning(s)');
    expect(existsSync(path.join(root, 'feat/d'))).toBe(true);
  });

  it('warns but continues when the remote is unreachable', () => {
    const repo = makeRepo({ primary: 'release' });
    gitIn(repo.local, ['remote', 'set-url', 'origin', path.join(repo.root, 'missing.git')]);

    const run = runCli(repo.local, ['create', '-t', 'feat', '-n', 'e', '-y']);

    expect(run.output).toContain('Failed to fetch');
    expect(run.output).toContain('Workspace created successfully');
    expect(run.output).toContain('origin/release');
  });
});

describe('create: errors and collisions', () => {
  it('lists both local and remote branches when the base does not exist', () => {
    const repo = makeRepo({ primary: 'release' });

    const run = runCli(repo.local, ['create', '-t', 'feat', '-n', 'h', '-b', 'nope', '-y']);

    expect(run.output).toContain('not found locally or on the remote');
    expect(run.output).toContain('Remote branches');
    expect(run.output).toContain('Local branches');
  });

  it('refuses a branch name that already exists on the remote, with a remedy', () => {
    const repo = makeRepo({ primary: 'release', branches: ['feat/taken'] });
    gitIn(repo.local, ['fetch', '--quiet', '--prune']);

    const run = runCli(repo.local, ['create', '-t', 'feat', '-n', 'taken', '-y']);

    expect(run.output).toContain('already exists on');
    expect(run.output).toContain('git worktree add');
  });
});

describe('create: worktree placement and extras', () => {
  it('places a worktree as a sibling even when run from inside another worktree', () => {
    const repo = makeRepo({ primary: 'release', advanceRemote: true });
    runCli(repo.local, ['create', '-t', 'feat', '-n', 'first', '-y']);

    const run = runCli(path.join(repo.root, 'feat/first'), [
      'create',
      '-t',
      'feat',
      '-n',
      'second',
      '-y'
