import { execFileSync, spawnSync } from 'child_process';
import { mkdtempSync, mkdirSync, rmSync, writeFileSync, realpathSync } from 'fs';
import * as os from 'os';
import * as path from 'path';
import { fileURLToPath } from 'url';

const HERE = path.dirname(fileURLToPath(import.meta.url));

/** Repository root, derived from this file's location. */
export const REPO_ROOT = path.resolve(HERE, '..', '..');

/** The built CLI entry point. `pnpm test` builds before running. */
export const CLI = path.join(REPO_ROOT, 'dist', 'index.js');

const tempRoots: string[] = [];

/**
 * Create a temp directory that `cleanupFixtures()` will remove.
 *
 * The path is resolved through `realpath` because macOS hands out
 * `/var/folders/...` while git reports the canonical `/private/var/folders/...`
 * — comparing worktree paths would otherwise never match.
 */
export function makeTempDir(prefix = 'wf-test-'): string {
  const dir = realpathSync(mkdtempSync(path.join(os.tmpdir(), prefix)));
  tempRoots.push(dir);
  return dir;
}

/** Remove every temp directory created during the run. */
export function cleanupFixtures(): void {
  while (tempRoots.length > 0) {
    const dir = tempRoots.pop();
    if (dir) {
      rmSync(dir, { recursive: true, force: true });
    }
  }
}

function git(cwd: string, args: string[]): string {
  return execFileSync('git', args, {
    cwd,
    encoding: 'utf8',
    stdio: 'pipe',
    env: { ...process.env, GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_SYSTEM: '/dev/null' }
  });
}

export type Fixture = {
  /** Directory holding remote.git, seed/, local/ and any created worktrees. */
  root: string;
  /** The bare repository standing in for the remote. */
  remote: string;
  /** A checkout used to push changes "from someone else". */
  seed: string;
  /** The clone under test. */
  local: string;
  /** Push a new commit to `branch` on the remote, leaving the clone stale. */
  advanceRemote(branch: string, message?: string): string;
  /** Short SHA of a ref on the remote. */
  remoteTip(branch: string): string;
  /** Short SHA of HEAD in a directory under the fixture root. */
  tipOf(relativePath: string): string | null;
};

export type FixtureOptions = {
  /** Primary branch name; also becomes the remote's HEAD. */
  primary?: string;
  /** Extra branches to create and push. */
  branches?: string[];
  /** Push a second commit so the clone's local branch starts out stale. */
  advanceRemote?: boolean;
};

/**
 * Build an isolated bare "remote" plus a clone of it.
 *
 * `.env` is gitignored, matching how real projects treat it — otherwise it
 * registers as an uncommitted change and blocks `close`.
 */
export function makeRepo(options: FixtureOptions = {}): Fixture {
  const { primary = 'release', branches = [], advanceRemote = false } = options;

  const root = makeTempDir();
  const remote = path.join(root, 'remote.git');
  const seed = path.join(root, 'seed');
  const local = path.join(root, 'local');

  mkdirSync(remote, { recursive: true });
  git(root, ['init', '--quiet', '--bare', remote]);

  mkdirSync(seed, { recursive: true });
  git(seed, ['init', '--quiet']);
  git(seed, ['config', 'user.email', 'test@example.com']);
  git(seed, ['config', 'user.name', 'Test']);
  git(seed, ['checkout', '--quiet', '-b', primary]);
  writeFileSync(path.join(seed, 'file.txt'), 'v1\n', 'utf8');
  writeFileSync(path.join(seed, '.gitignore'), '.env\n', 'utf8');
  git(seed, ['add', '-A']);
  git(seed, ['commit', '--quiet', '-m', 'c1: initial']);
  git(seed, ['remote', 'add', 'origin', remote]);
  git(seed, ['push', '--quiet', '-u', 'origin', primary]);

  for (const branch of branches) {
    git(seed, ['checkout', '--quiet', '-b', branch, primary]);
    writeFileSync(path.join(seed, 'branch-marker.txt'), `${branch}\n`, 'utf8');
    git(seed, ['add', '-A']);
    git(seed, ['commit', '--quiet', '-m', `commit on ${branch}`]);
    git(seed, ['push', '--quiet', 'origin', branch]);
  }

  git(seed, ['checkout', '--quiet', primary]);
  git(remote, ['symbolic-ref', 'HEAD', `refs/heads/${primary}`]);
  git(root, ['clone', '--quiet', remote, local]);

  const fixture: Fixture = {
    root,
    remote,
    seed,
    local,
    advanceRemote(branch, message = 'remote moved ahead') {
      git(seed, ['checkout', '--quiet', branch]);
      writeFileSync(path.join(seed, 'file.txt'), 'v2\n', 'utf8');
      git(seed, ['commit', '--quiet', '-am', message]);
      git(seed, ['push', '--quiet', 'origin', branch]);
      return fixture.remoteTip(branch);
    },
    remoteTip(branch) {
      return git(remote, ['rev-parse', '--short', branch]).trim();
    },
    tipOf(relativePath) {
      const target = path.join(root, relativePath);
      const result = spawnSync('git', ['rev-parse', '--short', 'HEAD'], {
        cwd: target,
        encoding: 'utf8',
        stdio: 'pipe'
      });
      return result.status === 0 ? result.stdout.trim() : null;
    }
  };

  if (advanceRemote) {
    fixture.advanceRemote(primary);
  }

  return fixture;
}

export type CliResult = {
  status: number;
  stdout: string;
  stderr: string;
  /** stdout and stderr combined, for message assertions. */
  output: string;
};

/** Run the built CLI in `cwd`. Never throws on a non-zero exit. */
export function runCli(cwd: string, args: string[]): CliResult {
  const result = spawnSync(process.execPath, [CLI, ...args], {
    cwd,
    encoding: 'utf8',
    stdio: 'pipe',
    env: { ...process.env, FORCE_COLOR: '0', GIT_TERMINAL_PROMPT: '0' }
  });

  const stdout = result.stdout ?? '';
  const stderr = result.stderr ?? '';

  return { status: result.status ?? 1, stdout, stderr, output: stdout + stderr };
}

/** Run a git command in a fixture directory, returning trimmed stdout. */
export function gitIn(cwd: string, args: string[]): string {
  const result = spawnSync('git', args, { cwd, encoding: 'utf8', stdio: 'pipe' });
  return (result.stdout ?? '').trim();
}

/** True when the branch exists locally in `cwd`. */
export function branchExists(cwd: string, branch: string): boolean {
  const result = spawnSync('git', ['show-ref', '--verify', '--quiet', `refs/heads/${branch}`], {
    cwd,
    stdio: 'pipe'
  });
  return result.status === 0;
}

import { existsSync, mkdirSync, readdirSync, statSync, unlinkSync, copyFileSync, constants } from 'fs';
import * as path from 'path';
import { ProjectIdentifier } from './ProjectIdentifier.js';
import { ConfigManager } from './ConfigManager.js';
import { BackupInfo } from '../types/index.js';

/**
 * Backup Manager
 *
 * Manages environment file backups with automatic cleanup:
 * - Creates timestamped backups in ~/.workforge/backups/<project-id>/
 * - Maintains configurable maximum number of backups (default: 10)
 * - Auto-cleanup of old backups when limit exceeded
 * - Support for listing, restoring, and deleting backups
 */
export class BackupManager {
  private configManager: ConfigManager;
  private maxBackups!: number;
  private backupEnabled!: boolean;

  constructor(configManager?: ConfigManager) {
    this.configManager = configManager || new ConfigManager();
    this.loadConfig();
  }

  /**
   * Load backup configuration
   */
  private loadConfig(): void {
    try {
      const config = this.configManager.load();
      this.maxBackups = config.backup.maxBackupsPerProject;
      this.backupEnabled = config.backup.enabled;
    } catch {
      // Fallback to defaults
      this.maxBackups = 10;
      this.backupEnabled = true;
    }
  }

  /**
   * Create backup of an environment file
   *
   * @param envPath - Path to .env file to backup
   * @param repoRoot - Repository root (for project ID)
   * @returns Path to created backup file
   * @throws Error if backup fails
   */
  createBackup(envPath: string, repoRoot: string): string {
    if (!this.backupEnabled) {
      throw new Error('Backups are disabled in configuration');
    }

    if (!existsSync(envPath)) {
      throw new Error(`Environment file not found: ${envPath}`);
    }

    // Generate project ID (used for directory structure)
    const _projectId = ProjectIdentifier.generateId(repoRoot);

    // Get backup directory
    const backupDir = ProjectIdentifier.getBackupDir(repoRoot);

    // Create backup directory if it doesn't exist
    if (!existsSync(backupDir)) {
      mkdirSync(backupDir, { recursive: true });
    }

    // Generate timestamp-based backup filename. Timestamps are only
    // second-resolution, so two syncs in the same second would otherwise
    // overwrite each other's snapshot — claim the name exclusively and add a
    // suffix on collision.
    const timestamp = this.generateTimestamp();
    const backupPath = this.claimBackupPath(backupDir, timestamp);

    // Copy file to backup location
    try {
      copyFileSync(envPath, backupPath, constants.COPYFILE_EXCL);
    } catch (error) {
      throw new Error(`Failed to create backup: ${error}`);
    }

    // Cleanup old backups if needed
    if (this.configManager.load().backup.autoCleanup) {
      this.cleanupOldBackups(backupDir);
    }

    return backupPath;
  }

  /**
   * List all backups for a project
   *
   * @param repoRoot - Repository root
   * @returns Array of backup information
   */
  listBackups(repoRoot: string): BackupInfo[] {
    const backupDir = ProjectIdentifier.getBackupDir(repoRoot);

    if (!existsSync(backupDir)) {
      return [];
    }

    const files = readdirSync(backupDir);
    const backups: BackupInfo[] = [];

    for (const file of files) {
      if (file.startsWith('.env.backup.')) {
        const filePath = path.join(backupDir, file);
        const stats = statSync(filePath);

        // Extract timestamp from filename
        const timestampMatch = file.match(/\.env\.backup\.(.+)$/);
        const _timestamp = timestampMatch ? timestampMatch[1] : '';

        backups.push({
          fileName: file,
          filePath,
          createdAt: stats.mtime,
          size: stats.size,
          timestamp: stats.mtime,
          ageInDays: Math.floor((Date.now() - stats.mtime.getTime()) / (1000 * 60 * 60 * 24))
        });
      }
    }

    // Sort by creation time (newest first)
    backups.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());

    return backups;
  }

  /**
   * Restore a backup to a target location
   *
   * @param backupPath - Path to backup file
   * @param targetPath - Target path to restore to
   * @throws Error if restore fails
   */
  restore(backupPath: string, targetPath: string): void {
    if (!existsSync(backupPath)) {
      throw new Error(`Backup file not found: ${backupPath}`);
    }

    try {
      copyFileSync(backupPath, targetPath);
    } catch (error) {
      throw new Error(`Failed to restore backup: ${error}`);
    }
  }

  /**
   * Delete a specific backup
   *
   * @param backupPath - Path to backup file to delete
   * @throws Error if deletion fails
   */
  deleteBackup(backupPath: string): void {
    if (!existsSync(backupPath)) {
      throw new Error(`Backup file not found: ${backupPath}`);
    }

    try {
      unlinkSync(backupPath);
    } catch (error) {
      throw new Error(`Failed to delete backup: ${error}`);
    }
  }

  /**
   * Cleanup old backups, keeping only the most recent N backups
   *
   * @param backupDir - Backup directory path
   */
  private cleanupOldBackups(backupDir: string): void {
    if (!existsSync(backupDir)) {
      return;
    }

    const files = readdirSync(backupDir);
    const backupFiles: { name: string; path: string; mtime: Date }[] = [];

    // Collect all backup files with their modification times
    for (const file of files) {
      if (file.startsWith('.env.backup.')) {
        const filePath = path.join(backupDir, file);
        const stats = statSync(filePath);

        backupFiles.push({
          name: file,
          path: filePath,
          mtime: stats.mtime
        });
      }
    }

    // Sort by modification time (newest first)
    backupFiles.sort((a, b) => b.mtime.getTime() - a.mtime.getTime());

    // Delete backups beyond the limit
    if (backupFiles.length > this.maxBackups) {
      const toDelete = backupFiles.slice(this.maxBackups);

      for (const backup of toDelete) {
        try {
          unlinkSync(backup.path);
        } catch (error) {
          console.warn(`Warning: Failed to delete old backup ${backup.name}: ${error}`);
        }
      }
    }
  }

  /**
   * Generate timestamp for backup filename
   *
   * Format: YYYY-MM-DD_HH-mm-ss
   *
   * @returns Timestamp string
   */
  /**
   * Pick a backup path that no existing backup already occupies
   *
   * @param backupDir - Directory backups live in
   * @param timestamp - Second-resolution timestamp
   */
  private claimBackupPath(backupDir: string, timestamp: string): string {
    const base = path.join(backupDir, `.env.backup.${timestamp}`);

    if (!existsSync(base)) {
      return base;
    }

    for (let suffix = 1; suffix < 1000; suffix++) {
      const candidate = `${base}-${suffix}`;
      if (!existsSync(candidate)) {
        return candidate;
      }
    }

    throw new Error(`Failed to create backup: too many backups for ${timestamp}`);
  }

  private generateTimestamp(): string {
    const now = new Date();

    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const seconds = String(now.getSeconds()).padStart(2, '0');

    return `${year}-${month}-${day}_${hours}-${minutes}-${seconds}`;
  }

  /**
   * Get the most recent backup for a project
   *
   * @param repoRoot - Repository root
   * @returns Most recent backup info or null if none exist
   */
  getMostRecentBackup(repoRoot: string): BackupInfo | null {
    const backups = this.listBackups(repoRoot);

    if (backups.length === 0) {
      return null;
    }

    return backups[0]; // Already sorted by creation time (newest first)
  }

  /**
   * Get total size of all backups for a project
   *
   * @param repoRoot - Repository root
   * @returns Total size in bytes
   */
  getTotalBackupSize(repoRoot: string): number {
    const backups = this.listBackups(repoRoot);
    return backups.reduce((total, backup) => total + backup.size, 0);
  }

  /**
   * Delete all backups for a project
   *
   * @param repoRoot - Repository root
   * @returns Number of backups deleted
   */
  deleteAllBackups(repoRoot: string): number {
    const backups = this.listBackups(repoRoot);
    let deletedCount = 0;

    for (const backup of backups) {
      try {
        unlinkSync(backup.filePath);
        deletedCount++;
      } catch (error) {
        console.warn(`Warning: Failed to delete backup ${backup.fileName}: ${error}`);
      }
    }

    return deletedCount;
  }

  /**
   * Delete backups older than a specific date
   *
   * @param repoRoot - Repository root
   * @param olderThan - Date threshold
   * @returns Number of backups deleted
   */
  deleteBackupsOlderThan(repoRoot: string, olderThan: Date): number {
    const backups = this.listBackups(repoRoot);
    let deletedCount = 0;

    for (const backup of backups) {
      if (backup.createdAt < olderThan) {
        try {
          unlinkSync(backup.filePath);
          deletedCount++;
        } catch (error) {
          console.warn(`Warning: Failed to delete backup ${backup.fileName}: ${error}`);
        }
      }
    }

    return deletedCount;
  }

  /**
   * Check if backups exist for a project
   *
   * @param repoRoot - Repository root
   * @returns True if backups exist
   */
  hasBackups(repoRoot: string): boolean {
    const backups = this.listBackups(repoRoot);
    return backups.length > 0;
  }

  /**
   * Get backup count for a project
   *
   * @param repoRoot - Repository root
   * @returns Number of backups
   */
  getBackupCount(repoRoot: string): number {
    const backups = this.listBackups(repoRoot);
    return backups.length;
  }

  /**
   * Format backup size for display
   *
   * @param bytes - Size in bytes
   * @returns Formatted string (e.g., "1.5 KB", "2.3 MB")
   */
  formatSize(bytes: number): string {
    if (bytes < 1024) {
      return `${bytes} B`;
    } else if (bytes < 1024 * 1024) {
      return `${(bytes / 1024).toFixed(1)} KB`;
    } else {
      return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
    }
  }

  /**
   * Format backup age for display
   *
   * @param createdAt - Backup creation date
   * @returns Formatted string (e.g., "2 hours ago", "3 days ago")
   */
  formatAge(createdAt: Date): string {
    const now = new Date();
    const diffMs = now.getTime() - createdAt.getTime();
    const diffMinutes = Math.floor(diffMs / (1000 * 60));
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

    if (diffMinutes < 60) {
      return `${diffMinutes} minute${diffMinutes === 1 ? '' : 's'} ago`;
    } else if (diffHours < 24) {
      return `${diffHours} hour${diffHours === 1 ? '' : 's'} ago`;
    } else {
      return `${diffDays} day${diffDays === 1 ? '' : 's'} ago`;
    }
  }
}

{
  "parser": "@typescript-eslint/parser",
  "parserOptions": {
    "ecmaVersion": 2022,
    "sourceType": "module",
    "project": "./tsconfig.json"
  },
  "plugins": ["@typescript-eslint"],
  "extends": [
    "eslint:recommended",
    "plugin:@typescript-eslint/recommended"
  ],
  "rules": {
